var publicScripts = String.raw`
const categoryGlyph={'دولت و هویت':'◎','مالیات و مجوز':'▤','بیمه و رفاه':'♡','آموزش و آزمون':'✎','قضایی و ثبت':'⚖','خودرو و انتظامی':'◇','مسکن و املاک':'⌂','پست و ارتباطات':'✉','بانک و بازار سرمایه':'▥','ابزارهای کاری':'⌘'};
const normalize=s=>String(s||'').toLowerCase().replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\u200c\s]+/g,' ').trim();
function savedIds(){try{const v=JSON.parse(localStorage.getItem('kfy-sites-saved')||'[]');return new Set(Array.isArray(v)?v:[])}catch{return new Set()}}
function saveId(id){const saved=savedIds();saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('kfy-sites-saved',JSON.stringify([...saved]))}catch{toast('ذخیره در این مرورگر ممکن نیست.');return false}return true}
function persianDay(s){return s?new Date(s+'T12:00:00+03:30').toLocaleDateString('fa-IR',{year:'numeric',month:'long',day:'numeric',timeZone:'Asia/Tehran'}):'—'}
const sites=()=>siteContent.filter(x=>x.kind==='site'),articles=()=>siteContent.filter(x=>x.kind==='article'||x.kind==='news');
function articleMeta(x){return {category:'اخبار',summary:x.body.slice(0,130),preparedAt:new Date(x.updated_at).toISOString().slice(0,10),sourceTitle:'منبع مرتبط',sourceUrl:x.url,...(x.meta||{})}}
function initTheme(){let mode='light';try{mode=localStorage.getItem('kfy-theme')||'light'}catch{}document.documentElement.classList.toggle('light',mode==='light');const b=$('#themeToggle');if(b){b.textContent=mode==='light'?'☾':'☀';b.onclick=()=>{const light=document.documentElement.classList.toggle('light');b.textContent=light?'☾':'☀';try{localStorage.setItem('kfy-theme',light?'light':'dark')}catch{}}}}
initTheme();
function siteCard(x){const m=x.meta||{},saved=savedIds().has(x.id);return '<article class="catalog-card"><div class="row between"><span class="glyph">'+(categoryGlyph[m.category]||'◎')+'</span><button class="save" data-save="'+x.id+'" aria-label="نشان‌کردن '+esc(x.title)+'" aria-pressed="'+saved+'">'+(saved?'★':'☆')+'</button></div><span class="small">'+esc(m.category||'سایر')+'</span><h3>'+esc(x.title)+'</h3><p>'+esc(x.body)+'</p><span class="domain">'+esc(new URL(x.url).hostname)+'</span><div class="card-actions"><a class="button primary" href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">ورود به سایت ↗</a><button data-site-detail="'+x.id+'">جزئیات</button></div></article>'}
function articleCard(x,i=0){const m=articleMeta(x);return '<article class="catalog-card article-card"><a class="article-cover c'+i%4+'" href="/articles/'+encodeURIComponent(x.id)+'" aria-label="'+esc(x.title)+'"><span>'+esc(m.category||'راهنما')+'</span><span class="glyph">'+(m.type==='news'?'▤':'✎')+'</span></a><div class="meta-row"><span>'+(m.type==='news'?'خلاصه خبر':'راهنمای کاربردی')+'</span><span>'+persianDay(m.sourceDate||m.preparedAt)+'</span></div><h3><a href="/articles/'+encodeURIComponent(x.id)+'" style="color:var(--text)">'+esc(x.title)+'</a></h3><p>'+esc(m.summary||x.body.slice(0,130))+'</p><div class="card-actions"><a href="/articles/'+encodeURIComponent(x.id)+'">مطالعه مطلب ←</a><span class="small">'+fa(m.readingMinutes||1)+' دقیقه</span></div></article>'}
function bindSites(refresh){document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{if(saveId(b.dataset.save)){refresh?.();if(!refresh){const on=savedIds().has(b.dataset.save);b.textContent=on?'★':'☆';b.setAttribute('aria-pressed',String(on))}}});document.querySelectorAll('[data-site-detail]').forEach(b=>b.onclick=()=>{const x=sites().find(x=>x.id===b.dataset.siteDetail),m=x.meta||{};modal(x.title,'<p>'+esc(x.body)+'</p><p class="small">دسته: '+esc(m.category||'سایر')+'</p><code>'+esc(x.url)+'</code><p class="access-note">'+(m.access==='responded'?'در بررسی فنی، پاسخ HTTP دریافت شد؛ این به معنای تأیید ورود یا انجام خدمات نیست.':m.access==='restricted'?'دسترسی ابزار بررسی محدود بود؛ وضعیت فعلی سرویس تأیید نشده است.':'دسترسی مستقیم از محیط بررسی تأیید نشد؛ ممکن است به شبکهٔ داخل ایران نیاز باشد.')+'</p>'+(m.checkedAt?'<p class="small">تاریخ بررسی: '+persianDay(m.checkedAt)+'</p>':'')+'<div class="row"><a class="button primary" href="'+esc(x.url)+'" target="_blank" rel="noopener noreferrer">بازکردن سایت ↗</a><button id="copySite">کپی نشانی</button></div>');$('#copySite').onclick=async()=>{try{await navigator.clipboard.writeText(x.url);toast('نشانی کپی شد.')}catch{toast('نشانی نمایش‌داده‌شده را انتخاب و کپی کنید.')}}})}
function publicFooter(){document.querySelector('footer').outerHTML='<footer class="public-footer"><div><strong>'+esc(settings.title||'کافی‌نت‌یار')+'</strong><br>فضای کاری فارسی برای کارهای روزمرهٔ کافی‌نت</div><div class="row"><a href="/sites">بانک سامانه‌ها</a><a href="/news">مقاله‌ها و اخبار</a><a href="/#faq">پرسش‌های رایج</a><a href="/admin">مدیریت</a></div></footer>'}
async function landing(){await publicData();publicFooter();const catalog=sites(),posts=articles(),categories=[...new Set(catalog.map(x=>x.meta?.category))];$('#app').innerHTML='<section class="public-hero"><div><span class="eyebrow">برای کافی‌نت‌دار، کارمند شیفت و مدیر مجموعه</span><h1>همهٔ کارهای کافی‌نت،<br>در یک <em>فضای مرتب‌تر.</em></h1><p>'+esc(settings.tagline||'از دفتر مالی روزانه تا سامانه‌های پرمراجعه و راهنماهای کاربردی؛ ابزارهای موردنیازت را سریع‌تر پیدا کن و با تمرکز بیشتری کار کن.')+'</p><div class="row hero-actions"><a class="button primary" href="/dashboard">ورود به فضای کاری ←</a><a class="button" href="/sites">بانک سامانه‌ها</a></div><span class="small">فارسی و راست‌به‌چپ · روشن و تاریک · مناسب موبایل</span></div><div class="workspace-preview"><div class="row between"><div><strong>میز کار کافی‌نت‌یار</strong><div class="small">میان‌برهای روزانه، همیشه دم دست</div></div><span class="mark">CY</span></div><div class="preview-grid">'+[['/sites?category='+encodeURIComponent('دولت و هویت'),'◎','دولت و هویت'],['/sites?category='+encodeURIComponent('آموزش و آزمون'),'✎','آموزش'],['/sites?category='+encodeURIComponent('بیمه و رفاه'),'♡','بیمه'],['/sites?category='+encodeURIComponent('مالیات و مجوز'),'▤','مالیات'],['/sites?category='+encodeURIComponent('پست و ارتباطات'),'✉','پست'],['/news','▧','راهنماها']].map(x=>'<a class="quick-tile" href="'+x[0]+'"><span class="glyph">'+x[1]+'</span>'+x[2]+'</a>').join('')+'</div><div class="mini-line"><span>بانک سامانه‌های کاربردی</span><strong>'+fa(catalog.length)+' نشانی</strong></div><div class="mini-line"><span>مقاله و راهنمای منتشرشده</span><strong>'+fa(posts.length)+' مطلب</strong></div></div></section><section class="stats-strip"><span><strong>'+fa(catalog.length)+'</strong>سایت کاربردی</span><span><strong>'+fa(categories.length)+'</strong>دسته‌بندی</span><span><strong>'+fa(posts.length)+'</strong>مطلب خواندنی</span><span class="muted">یک نقطهٔ شروع برای کارهای روزانه</span></section><section class="public-section"><div class="section-heading"><div><span class="eyebrow">دسترسی سریع</span><h2>دنبال کدام سامانه می‌گردی؟</h2><p>نام سایت یا خدمت را بنویس؛ مثلاً بیمه، مالیات یا کد پستی.</p></div><a href="/sites">همهٔ سامانه‌ها ←</a></div><form class="searchbox" action="/sites"><input name="q" aria-label="جست‌وجوی سامانه" placeholder="نام سامانه، خدمت یا نشانی…"><button class="primary">جست‌وجو ←</button></form><div class="catalog-grid">'+catalog.filter(x=>['my.gov.ir','my.tax.gov.ir','www.sanjesh.org','eservices.tamin.ir','tracking.post.ir','sakha.epolice.ir'].includes(new URL(x.url).hostname)).map(siteCard).join('')+'</div></section><section class="public-section"><div class="section-heading"><div><span class="eyebrow">مجلهٔ کافی‌نت‌یار</span><h2>تازه بخوان، مطمئن‌تر انجام بده</h2><p>خبرهای دارای منبع و راهنماهای کوتاه برای کار روزمره.</p></div><a href="/news">همهٔ مطالب ←</a></div><div class="catalog-grid">'+posts.slice(0,3).map(articleCard).join('')+'</div></section><section class="public-section"><div class="section-heading"><div><span class="eyebrow">فضای کاری شما</span><h2>از دریافت مشتری تا جمع‌بندی روز</h2></div></div><div class="catalog-grid">'+[['▥','دفتر مالی روزانه','درآمد و هزینه را ثبت کن و جمع مبالغ ثبت‌شده را ببین.','/dashboard'],['◎','سامانه‌ها و نشانک‌ها','سایت‌های پرمراجعه را جست‌وجو کن و در همین مرورگر نشان کن.','/sites'],['✉','پیگیری پشتیبانی','درخواست‌ها و پاسخ‌ها را داخل حساب خودت نگه دار.','/dashboard']].map(x=>'<article class="catalog-card feature-card"><span class="glyph">'+x[0]+'</span><h3>'+x[1]+'</h3><p>'+x[2]+'</p><a href="'+x[3]+'">شروع کار ←</a></article>').join('')+'</div></section>'+(siteContent.some(x=>['service','plan','page'].includes(x.kind))?'<section class="public-section"><h2>خدمات و اطلاع‌رسانی مجموعه</h2><div class="catalog-grid">'+siteContent.filter(x=>['service','plan','page'].includes(x.kind)).map(cardContent).join('')+'</div></section>':'')+'<section class="public-section card" id="faq"><h2>چند سؤال رایج</h2><details><summary>سامانه‌های داخل فهرست متعلق به کافی‌نت‌یار هستند؟</summary><p class="muted">خیر؛ لینک‌ها شما را به سایت سازمان یا ارائه‌دهندهٔ خدمت می‌برند. اطلاعات ورود و پرداخت را در همان سامانهٔ مقصد بررسی کنید.</p></details><details><summary>آیا فهرست، همهٔ سایت‌های ایران را پوشش می‌دهد؟</summary><p class="muted">این مجموعه از سامانه‌های پرکاربرد کافی‌نت‌ها شروع شده و از پنل مدیریت قابل گسترش است. عنوان دسته یا نام خدمت را جست‌وجو کنید.</p></details><details><summary>چرا بعضی سامانه‌ها باز نمی‌شوند؟</summary><p class="muted">اختلال، محدودیت شبکه، نیاز به اینترنت داخل کشور یا تغییر نشانی می‌تواند علت باشد. جزئیات کارت، نتیجهٔ آخرین بررسی را نشان می‌دهد؛ هیچ کارت تضمین دسترسی لحظه‌ای نیست.</p></details><details><summary>مطالب به‌صورت خودکار به‌روز می‌شوند؟</summary><p class="muted">خیر؛ این مجموعهٔ منتخب با منبع و تاریخ تهیه منتشر شده است. برای مهلت‌ها و شرایط جاری، اطلاعیهٔ مرجع اصلی را بخوانید.</p></details></section><section class="cta-panel"><div><h2>کارت را از یک جای مرتب شروع کن.</h2><p>سامانه‌ها، راهنماها و دفتر روزانه در کنار هم.</p></div><a class="button primary" href="/dashboard">ورود به فضای کاری ←</a></section>'+(settings.contact?'<section class="public-section card"><h2>ارتباط با ما</h2><p class="pre">'+esc(settings.contact)+'</p></section>':'');bindSites();}
async function directory(){await publicData();publicFooter();const params=new URLSearchParams(location.search);let category=params.get('category')||'',q=params.get('q')||'',onlySaved=false;const catalog=sites(),categories=[...new Set(catalog.map(x=>x.meta?.category||'سایر'))];$('#app').innerHTML='<section class="library-head"><span class="eyebrow">بانک سامانه‌های کافی‌نت‌یار</span><h1>هر سامانه، یک کلیک دورتر</h1><p class="muted">'+fa(catalog.length)+' نشانی در '+fa(categories.length)+' دسته؛ از خدمات دولتی تا ابزارهای روزمره.</p><div class="searchbox"><input id="catalogSearch" value="'+esc(q)+'" placeholder="نام، خدمت یا دامنه…" aria-label="جست‌وجوی سامانه"><button id="clearSearch">پاک‌کردن</button></div><div class="chips" id="categories"></div><div class="row between"><button id="onlySaved" aria-pressed="false">☆ نشان‌شده‌ها در این مرورگر</button><label style="display:flex;align-items:center;margin:0">مرتب‌سازی<select id="catalogSort"><option value="category">دسته‌بندی</option><option value="name">نام سامانه</option></select></label></div><p class="small section-title">این فهرست وضعیت زندهٔ سامانه‌ها را تضمین نمی‌کند. نتیجهٔ بررسی در «جزئیات» هر کارت آمده است.</p></section><p class="small" id="catalogCount" role="status"></p><div id="catalogResults" class="catalog-grid"></div>';
 function draw(){const needle=normalize(q);let rows=catalog.filter(x=>(!category||x.meta?.category===category)&&(!onlySaved||savedIds().has(x.id))&&normalize(x.title+' '+x.body+' '+x.url).includes(needle));if($('#catalogSort').value==='name')rows.sort((a,b)=>a.title.localeCompare(b.title,'fa'));$('#catalogCount').textContent=fa(rows.length)+' سامانه پیدا شد';$('#categories').innerHTML=['',...categories].map(c=>'<button class="chip '+(c===category?'active':'')+'" data-category="'+esc(c)+'">'+esc(c||'همه دسته‌ها')+'</button>').join('');$('#catalogResults').innerHTML=rows.length?rows.map(siteCard).join(''):'<div class="card empty">سامانه‌ای پیدا نشد. جست‌وجو یا دسته‌بندی را تغییر بده.</div>';document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;draw()});$('#onlySaved').setAttribute('aria-pressed',String(onlySaved));$('#onlySaved').classList.toggle('primary',onlySaved);const p=new URLSearchParams();if(q)p.set('q',q);if(category)p.set('category',category);history.replaceState(null,'','/sites'+(p.size?'?'+p:''));bindSites(draw)}
 $('#catalogSearch').oninput=e=>{q=e.target.value;draw()};$('#clearSearch').onclick=()=>{q='';category='';onlySaved=false;$('#catalogSearch').value='';draw()};$('#onlySaved').onclick=()=>{onlySaved=!onlySaved;draw()};$('#catalogSort').onchange=draw;draw();}
async function newsroom(){await publicData();publicFooter();let cat='';const posts=articles();$('#app').innerHTML='<section class="library-head"><span class="eyebrow">مجلهٔ کافی‌نت‌یار</span><h1>مقاله‌ها، راهنماها و خبرها</h1><p class="muted">مطالعهٔ کوتاه برای انجام بهتر کارهای روزمره؛ با منبع قابل پیگیری.</p><div class="searchbox"><input id="articleSearch" placeholder="جست‌وجو در مطالب…" aria-label="جست‌وجوی مقاله"></div><div class="chips" id="articleCategories"></div></section><div id="articleResults" class="catalog-grid"></div>';function draw(){const cats=[...new Set(posts.map(x=>articleMeta(x).category))];$('#articleCategories').innerHTML=['',...cats].map(c=>'<button class="chip '+(c===cat?'active':'')+'" data-ac="'+esc(c)+'">'+esc(c||'همه مطالب')+'</button>').join('');const rows=posts.filter(x=>(!cat||articleMeta(x).category===cat)&&normalize(x.title+' '+x.body).includes(normalize($('#articleSearch').value)));$('#articleResults').innerHTML=rows.length?rows.map(articleCard).join(''):'<div class="empty">مطلبی پیدا نشد.</div>';document.querySelectorAll('[data-ac]').forEach(b=>b.onclick=()=>{cat=b.dataset.ac;draw()})}$('#articleSearch').oninput=draw;draw();}
async function articlePage(){await publicData();publicFooter();const id=decodeURIComponent(location.pathname.split('/').pop()),x=articles().find(x=>x.id===id);if(!x){$('#app').innerHTML='<section class="card empty"><h1>این مطلب پیدا نشد</h1><a href="/news">بازگشت به مجله</a></section>';return;}const m=articleMeta(x);document.title=x.title+' | کافی‌نت‌یار';$('#app').innerHTML='<p class="small"><a href="/">خانه</a> / <a href="/news">مجله</a> / '+esc(m.category)+'</p><div class="article-layout"><article class="card"><span class="pill">'+(m.type==='news'?'خلاصه خبر با منبع':'راهنمای کاربردی')+'</span><h1 class="section-title">'+esc(x.title)+'</h1><div class="meta-row"><span>تهیه و بررسی: '+persianDay(m.preparedAt)+'</span>'+(m.sourceDate?'<span>انتشار منبع: '+persianDay(m.sourceDate)+'</span>':'')+'<span>تحریریهٔ کافی‌نت‌یار</span></div><p class="section-title muted">'+esc(m.summary||'')+'</p><div class="article-body">'+x.body.split('\n\n').map(p=>'<p class="pre">'+esc(p)+'</p>').join('')+'</div><div class="notice">'+(m.type==='news'?'این متن خلاصهٔ مستقل خبر است؛ جزئیات و اصلاحیه‌های احتمالی را از منبع بخوانید.':'این مطلب راهنمای عمومی است؛ شرایط، هزینه‌ها و مهلت‌های هر خدمت را از سامانهٔ رسمی بررسی کنید.')+'</div></article><aside class="card article-sidebar"><h3>منبع و مسیر ادامه</h3><p class="small">'+esc(m.sourceTitle||'منبع مرتبط')+'</p>'+(m.sourceUrl||x.url?'<a class="button primary" href="'+esc(m.sourceUrl||x.url)+'" target="_blank" rel="noopener noreferrer">مشاهده منبع ↗</a>':'')+'<hr style="border:0;border-top:1px solid var(--line);margin:25px 0"><h3>دسترسی سریع</h3><p><a href="/sites">بانک سامانه‌ها ←</a></p><p><a href="/news">مقاله‌های بیشتر ←</a></p><button id="printArticle">چاپ راهنما</button></aside></div>';$('#printArticle').onclick=()=>window.print();}
`;

