const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fa=n=>Number(n||0).toLocaleString('fa-IR'),date=n=>n?new Date(n).toLocaleString('fa-IR',{timeZone:'Asia/Tehran'}):'\u062B\u0628\u062A \u0646\u0634\u062F\u0647';
let me=null,current='overview',settings={},records=[],siteContent=[];
