function login(message=''){me=null;$('#app').innerHTML='<section class="card login"><span class="pill">\u0648\u0631\u0648\u062F \u0627\u0645\u0646</span><h1 class="section-title">\u0628\u0647 \u06A9\u0627\u0641\u06CC\u200C\u0646\u062A\u200C\u06CC\u0627\u0631 \u062E\u0648\u0634 \u0622\u0645\u062F\u06CC\u062F</h1><p class="muted">\u0628\u0627 \u062D\u0633\u0627\u0628 \u0645\u0633\u062A\u0642\u0644 \u0633\u0627\u06CC\u062A \u0648\u0627\u0631\u062F \u0645\u062F\u06CC\u0631\u06CC\u062A \u0634\u0648\u06CC\u062F. \u0628\u0631\u0627\u06CC \u0631\u0627\u0647\u200C\u0627\u0646\u062F\u0627\u0632\u06CC \u0627\u0648\u0644\u06CC\u0647 \u062F\u0631 \u0645\u06CC\u0632\u0628\u0627\u0646\u06CC \u0641\u0639\u0644\u06CC\u060C \u0645\u0627\u0644\u06A9 \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u0627\u0632 \u0648\u0631\u0648\u062F \u062D\u0633\u0627\u0628 \u0633\u0627\u0632\u0646\u062F\u0647 \u0627\u0633\u062A\u0641\u0627\u062F\u0647 \u06A9\u0646\u062F.</p><a class="button primary" href="/auth?returnTo=%2Fmanage">\u0648\u0631\u0648\u062F \u0628\u0627 \u0634\u0645\u0627\u0631\u0647 \u0648 \u0631\u0645\u0632 \u0633\u0627\u06CC\u062A</a>'+(message?'<p class="notice">'+esc(message)+'</p>':'')+'<button class="primary" id="enter">\u0648\u0631\u0648\u062F \u0628\u0647 \u067E\u0646\u0644</button><p class="small section-title">\u0631\u0648\u06CC \u0647\u0627\u0633\u062A \u0644\u06CC\u0646\u0648\u06A9\u0633 \u0648\u0631\u0648\u062F \u0628\u0627 \u0634\u0645\u0627\u0631\u0647 \u0648 \u0631\u0645\u0632 \u0645\u0633\u062A\u0642\u0644 \u0627\u0646\u062C\u0627\u0645 \u0645\u06CC\u200C\u0634\u0648\u062F.</p><a target="_top" href="/signin-with-chatgpt?return_to=%2Fmanage">\u0648\u0631\u0648\u062F \u06CC\u0627 \u062A\u063A\u06CC\u06CC\u0631 \u062D\u0633\u0627\u0628 ChatGPT</a></section>';$('#enter').onclick=async()=>{try{$('#enter').disabled=true;await api('session',{});await boot()}catch(e){login(e.message)}}}
